    request.setItens(Arrays.asList(
        new ItemRequest("Camiseta", new BigDecimal("79.90"), 2, new BigDecimal("0.30")),
        new ItemRequest("Tênis", new BigDecimal("249.90"), 1, new BigDecimal("1.20"))
    ));
