package com.loja.checkout.controller;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.loja.checkout.dto.CheckoutRequest;
import com.loja.checkout.dto.ItemRequest;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.Collections;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest
@AutoConfigureMockMvc
class CheckoutControllerTest {

  @Autowired
  private MockMvc mockMvc;

  @Autowired
  private ObjectMapper objectMapper;

  @Test
  void testErro1_CarrinhoVazio() throws Exception {
    CheckoutRequest request = new CheckoutRequest();
    request.setItens(Collections.emptyList());
    request.setModalidadeEntrega("EXPRESSA");
    request.setFormaPagamento("PIX");
    request.setNivelClube("BRONZE");

    mockMvc.perform(post("/checkout/resumo")
        .contentType(MediaType.APPLICATION_JSON)
        .content(objectMapper.writeValueAsString(request)))
        .andExpect(status().isBadRequest())
        .andExpect(jsonPath("$.erro").value("PEDIDO_INVALIDO"));
  }

  @Test
  void testErro1_ItemComPrecoZero() throws Exception {
    CheckoutRequest request = new CheckoutRequest();
    request.setItens(Arrays.asList(
        new ItemRequest("Produto", BigDecimal.ZERO, 1, new BigDecimal("0.5"))
    ));
    request.setModalidadeEntrega("EXPRESSA");
    request.setFormaPagamento("PIX");
    request.setNivelClube("BRONZE");

    mockMvc.perform(post("/checkout/resumo")
        .contentType(MediaType.APPLICATION_JSON)
        .content(objectMapper.writeValueAsString(request)))
        .andExpect(status().isBadRequest())
        .andExpect(jsonPath("$.erro").value("PEDIDO_INVALIDO"));
  }

  @Test
  void testErro2_NivelClubeInvalido() throws Exception {
    CheckoutRequest request = new CheckoutRequest();
    request.setItens(Arrays.asList(
        new ItemRequest("Produto", new BigDecimal("100"), 1, new BigDecimal("0.5"))
    ));
    request.setModalidadeEntrega("EXPRESSA");
    request.setFormaPagamento("PIX");
    request.setNivelClube("INVALIDO");

    mockMvc.perform(post("/checkout/resumo")
        .contentType(MediaType.APPLICATION_JSON)
        .content(objectMapper.writeValueAsString(request)))
        .andExpect(status().isBadRequest())
        .andExpect(jsonPath("$.erro").value("NIVEL_CLUBE_INVALIDO"));
  }

  @Test
  void testErro2_NivelClubeAusente() throws Exception {
    CheckoutRequest request = new CheckoutRequest();
    request.setItens(Arrays.asList(
        new ItemRequest("Produto", new BigDecimal("100"), 1, new BigDecimal("0.5"))
    ));
    request.setModalidadeEntrega("EXPRESSA");
    request.setFormaPagamento("PIX");
    request.setNivelClube(null);

    mockMvc.perform(post("/checkout/resumo")
        .contentType(MediaType.APPLICATION_JSON)
        .content(objectMapper.writeValueAsString(request)))
        .andExpect(status().isBadRequest())
        .andExpect(jsonPath("$.erro").value("NIVEL_CLUBE_INVALIDO"));
  }

  @Test
  void testErro3_RegiaoInvalida() throws Exception {
    CheckoutRequest request = new CheckoutRequest();
    request.setItens(Arrays.asList(
        new ItemRequest("Produto", new BigDecimal("100"), 1, new BigDecimal("0.5"))
    ));
    request.setModalidadeEntrega("EXPRESSA");
    request.setFormaPagamento("PIX");
    request.setNivelClube("BRONZE");
    request.setRegiao("INVALIDA");

    mockMvc.perform(post("/checkout/resumo")
        .contentType(MediaType.APPLICATION_JSON)
        .content(objectMapper.writeValueAsString(request)))
        .andExpect(status().isBadRequest())
        .andExpect(jsonPath("$.erro").value("REGIAO_INVALIDA"));
  }

  @Test
  void testErro4_ModalidadeInvalida() throws Exception {
    CheckoutRequest request = new CheckoutRequest();
    request.setItens(Arrays.asList(
        new ItemRequest("Produto", new BigDecimal("100"), 1, new BigDecimal("0.5"))
    ));
    request.setModalidadeEntrega("INVALIDA");
    request.setFormaPagamento("PIX");
    request.setNivelClube("BRONZE");

